do $$ begin if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='profit_distributions') then alter publication supabase_realtime add table public.profit_distributions; end if; if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='profit_distribution_payment_proofs') then alter publication supabase_realtime add table public.profit_distribution_payment_proofs; end if; end $$;